use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Returns true if the two file paths may correspond to the same file."] # [doc = ""] # [doc = " Note that it's possible for this to produce a false positive on some"] # [doc = " platforms. Namely, this can return true even if the two file paths *don't*"] # [doc = " resolve to the same file."] # [doc = " # Errors"] # [doc = " This function will return an [`io::Error`] if any of the two paths cannot"] # [doc = " be opened. The most common reasons for this are: the path does not exist,"] # [doc = " or there were not enough permissions."] # [doc = ""] # [doc = " [`io::Error`]: https://doc.rust-lang.org/std/io/struct.Error.html"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " use same_file::is_same_file;"] # [doc = ""] # [doc = " assert!(is_same_file(\"./foo\", \"././foo\").unwrap_or(false));"] # [doc = " ```"] pub fn is_same_file < P , Q > (path1 : P , path2 : Q) -> io :: Result < bool > where P : AsRef < Path > , Q : AsRef < Path > , { Ok (Handle :: from_path (path1) ? == Handle :: from_path (path2) ?) }